import { DomainError } from '../../../shared/domain/errors/domain-error';

/**
 * SHA-256 hash of a refresh token, stored hex-encoded.
 *
 * The plaintext refresh token is generated by `RandomRefreshTokenGenerator`
 * (32 bytes of crypto-grade random). The hash is what we persist; on every
 * refresh we re-hash the presented token and look up by hash. This way a
 * database leak does not yield usable tokens.
 *
 * Format: lowercase hex, exactly 64 characters (SHA-256 output).
 */
export class RefreshTokenHash {
  public readonly value: string;

  private constructor(value: string) {
    this.value = value;
  }

  /**
   * Compute the hash from a plaintext refresh token. Pure function —
   * use this wherever you need to compare a presented token to the
   * stored value.
   */
  public static async fromPlaintext(
    plaintext: string,
  ): Promise<RefreshTokenHash> {
    const { createHash } = await import('node:crypto');
    const hash = createHash('sha256').update(plaintext, 'utf8').digest('hex');
    return new RefreshTokenHash(hash);
  }

  /** Rehydrate from a stored value. Validates the format. */
  public static rehydrate(value: string): RefreshTokenHash {
    if (!/^[0-9a-f]{64}$/.test(value)) {
      throw new DomainError(
        'authentication.session.not_found',
        'Stored refresh-token hash is not a valid SHA-256 hex string',
      );
    }
    return new RefreshTokenHash(value);
  }

  public equals(other: RefreshTokenHash): boolean {
    return this.value === other.value;
  }

  public toString(): string {
    return this.value;
  }
}
